const el = document.getElementById('app')!;
async function load(){ const ctx = await FormLogic.context(); const fid = ctx.forms[0].formId; const rows = await FormLogic.records(fid, { limit: 100 }); el.innerHTML = '<h1>Tasks (' + rows.length + ')</h1>' + rows.map(r => '<div>' + FormLogic.escapeHtml(r.answers.title) + '</div>').join(''); }
load();
